import fs from "fs";
import zlib from "zlib";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
/* §276r5 Control Plane full sync - tested sandbox CP mirror, one shot. */
const PAYLOAD = "";
if (!fs.existsSync("package.json") || !fs.existsSync("app")) {
  console.log("X Run this from the WEBSITE repo root (folder with package.json + app/). Nothing was written.");
  process.exit(1);
}
const data = JSON.parse(zlib.gunzipSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
const BACKUP_TAG = ".pre_276r5.bak";
const norm = (s) => s.replace(/\r\n/g, "\n");
let applied = 0, already = 0, warnings = 0;
const hasCp = fs.existsSync("OmniFlow-Control-Plane") && fs.statSync("OmniFlow-Control-Plane").isDirectory();
function parent(p) { const cut = Math.max(p.lastIndexOf("/"), p.lastIndexOf("\\")); return cut > 0 ? p.slice(0, cut) : null; }
function backup(p) { const b = p + BACKUP_TAG; if (!fs.existsSync(b)) fs.copyFileSync(p, b); }
function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const r = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg]);
    return r.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeOne(target, content, isCp) {
  try {
    if (fs.existsSync(target)) {
      if (fs.statSync(target).isDirectory()) {
        let t = target + ".dir_conflict.bak", n = 1;
        while (fs.existsSync(t)) { t = target + ".dir_conflict.bak." + n; n++; }
        fs.renameSync(target, t); warnings++;
      } else if (norm(fs.readFileSync(target, "utf8")) === norm(content)) { already++; return true; }
      else backup(target);
    } else {
      const dir = parent(target); if (dir) fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(target, content, "utf8");
    if (isCp && target.endsWith(".py") && !compilePython(target)) {
      const b = target + BACKUP_TAG;
      if (fs.existsSync(b)) fs.copyFileSync(b, target); else fs.unlinkSync(target);
      console.log("X " + target + " FAILED to compile - old copy restored"); warnings++; return false;
    }
    applied++; return true;
  } catch (err) { console.log("X " + target + " FAILED: " + err.message); warnings++; return false; }
}
console.log("§276r5 CP sync: " + Object.keys(data.files).length + " files" + (hasCp ? "" : " (OmniFlow-Control-Plane/ NOT FOUND - mirror only!)"));
for (const [rel, content] of Object.entries(data.files)) {
  writeOne("omniflow-backend-patch/" + rel, content, false);
  if (hasCp) writeOne("OmniFlow-Control-Plane/" + rel, content, true);
}
for (const rel of data.deletes) {
  for (const base of ["omniflow-backend-patch", hasCp ? "OmniFlow-Control-Plane" : null]) {
    if (!base) continue;
    const p = base + "/" + rel;
    if (!fs.existsSync(p)) { already++; continue; }
    try { backup(p); fs.unlinkSync(p); applied++; } catch (err) { console.log("X " + p + " remove failed: " + err.message); warnings++; }
  }
}
console.log("");
console.log("applied=" + applied + " already=" + already + " warnings=" + warnings);
if (!hasCp) {
  console.log("");
  console.log("X OmniFlow-Control-Plane/ missing: clone the Control Plane repo into that");
  console.log("  folder (git clone <cp-repo-url> OmniFlow-Control-Plane) and run this again.");
  process.exit(0);
}
if (warnings > 0) { console.log("X warnings above - send this output before pushing the CP."); process.exit(0); }
console.log("");
console.log("Next (one line at a time):");
console.log("  cd OmniFlow-Control-Plane");
console.log("  git add -A");
console.log("  git commit -m \"cp: full sync to tested state (276r5)\"");
console.log("  git push");
console.log("  cd ..");
console.log("Vercel CP project: Redeploy (cache unchecked) -> then /api/v1/mobile/config must return JSON");
console.log("and the website admin cards turn green.");